+    const costs = acknowledged?.calculatedCosts;
+    return {
+      ...wall,
+      calculatedCosts: costs && typeof costs === "object" && !Array.isArray(costs) ? { ...costs } : {},
+    };
+  };
+  return walls.map((wall, index) => {
